// MOCK email inbox; consume the trigger input and emit exactly three sample emails.
$input.all();
const emails = [
  {
    id: 'E1',
    from: 'dana@example.com',
    subject: 'Quote request: basement finish',
    body: 'Hi, walls 1200 sqft, ceiling 400 sqft, standard board, level 4 finish. Thanks.'
  },
  {
    id: 'E2',
    from: 'lee@example.com',
    subject: 'Bathroom drywall',
    body: 'Need walls 300 sqft, ceiling 80 sqft, moisture resistant board, level 5.'
  },
  {
    id: 'E3',
    from: 'sam@example.com',
    subject: 'Garage',
    body: 'Can you quote my garage? level 4'
  }
];
return emails.map((email) => ({ json: email }));

// Deterministic regex STAND-IN for a later Claude extraction call; no AI service is called.
return $input.all().map(({ json: email }) => {
  const walls = email.body.match(/walls\s+(\d+)\s*sq\s*ft/i);
  const ceiling = email.body.match(/ceiling\s+(\d+)\s*sq\s*ft/i);
  const finish = email.body.match(/level\s+([345])\b/i);
  const job = {
    id: email.id,
    from: email.from,
    subject: email.subject,
    walls_sqft: walls ? parseInt(walls[1], 10) : null,
    ceiling_sqft: ceiling ? parseInt(ceiling[1], 10) : null,
    board: /standard board/i.test(email.body) ? 'standard' :
      /moisture[- ]resistant board/i.test(email.body) ? 'moisture' : null,
    finish_level: finish ? parseInt(finish[1], 10) : null
  };
  const missing = ['walls_sqft', 'ceiling_sqft', 'board', 'finish_level']
    .filter((field) => job[field] === null);
  return { json: { ...job, missing, complete: missing.length === 0 } };
});

// Placeholder pricing for this offline simulation; calculate using integer cents only.
return $input.all().map(({ json: job }) => {
  const area_sqft = job.walls_sqft + job.ceiling_sqft;
  const sheets = Math.floor((area_sqft * 110 + 3199) / 3200);
  const board_cents_per_sheet = job.board === 'standard' ? 1500 : 2200;
  const labor_cents_per_sqft = { 3: 150, 4: 180, 5: 230 }[job.finish_level];
  const materials_cents = sheets * board_cents_per_sheet;
  const labor_cents = area_sqft * labor_cents_per_sqft;
  const ceiling_surcharge_cents = 40 * job.ceiling_sqft;
  const subtotal_cents = materials_cents + labor_cents + ceiling_surcharge_cents;
  const margin_cents = Math.floor((subtotal_cents * 20 + 50) / 100);
  const total_cents = subtotal_cents + margin_cents;
  return { json: {
    ...job,
    area_sqft,
    sheets,
    board_cents_per_sheet,
    labor_cents_per_sqft,
    materials_cents,
    labor_cents,
    ceiling_surcharge_cents,
    subtotal_cents,
    margin_cents,
    total_cents
  } };
});

// MOCK GoHighLevel payload shape, not the real API; nothing is sent.
return $input.all().map(({ json: job }) => {
  const c = job.total_cents;
  const usd = (c - c % 100) / 100 + '.' + String(c % 100).padStart(2, '0');
  const line_items = [
    {
      name: 'Drywall board (' + job.board + ')',
      qty: job.sheets,
      unit_price_cents: job.board_cents_per_sheet
    },
    {
      name: 'Labor, level ' + job.finish_level + ' finish (sqft)',
      qty: job.area_sqft,
      unit_price_cents: job.labor_cents_per_sqft
    },
    {
      name: 'Ceiling surcharge (sqft)',
      qty: job.ceiling_sqft,
      unit_price_cents: 40
    },
    {
      name: 'Overhead and margin (20%)',
      qty: 1,
      unit_price_cents: job.margin_cents
    }
  ];
  return { json: { ghl_proposal: {
    contact: { email: job.from },
    estimate: {
      name: 'Drywall estimate ' + job.id + ' — ' + job.subject,
      currency: 'USD',
      line_items,
      total_cents: job.total_cents,
      total_usd: usd
    }
  } } };
});

return $input.all().map(({ json: job }) => ({ json: { review_task: {
  email_id: job.id,
  from: job.from,
  subject: job.subject,
  missing: job.missing,
  title: 'Review needed: ' + job.subject,
  note: 'Missing ' + job.missing.join(', ') + '; ask the customer before pricing.'
} } }));
